<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\StageDisplayService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$link=StageDisplayService::byToken($pdo,$token);if(!$link){http_response_code(404);exit('Stage Display link not found or expired.');}try{$data=StageDisplayService::payload($pdo,$link);}catch(Throwable $e){http_response_code(404);exit('Stage Display is unavailable.');}$round=$data['round'];$competitors=$data['competitors'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Stage Display</title><style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#07090f;color:#fff;font-family:Arial,sans-serif}.stage{height:100vh;max-width:56.25vh;margin:auto;position:relative;background:radial-gradient(circle at 50% 20%,#40101b,#111827 48%,#030509);display:flex;flex-direction:column}.head{padding:5vh 5vw 2vh;text-align:center}.event{font-size:2.7vh;font-weight:900}.division{font-size:1.7vh;letter-spacing:.14em;text-transform:uppercase;color:#ffb7c3;margin-top:.8vh}.test{position:absolute;top:1.5vh;right:1.5vh;background:#ffc107;color:#111;padding:.6vh 1vh;border-radius:999px;font-weight:900;font-size:1.2vh}.screen{flex:1;display:flex;align-items:center;justify-content:center;padding:2vh}.person{text-align:center;width:100%}.photo{width:34vh;height:34vh;border-radius:50%;object-fit:cover;border:.7vh solid rgba(255,255,255,.9);box-shadow:0 0 5vh rgba(209,15,50,.45);background:#252b36}.placeholder{width:34vh;height:34vh;border-radius:50%;margin:auto;display:flex;align-items:center;justify-content:center;background:#252b36;border:.7vh solid #fff;font-size:12vh}.name{font-size:4.3vh;font-weight:900;margin-top:2.5vh;line-height:1.05}.meta{font-size:2vh;margin-top:1.5vh;color:#d7dce5}.flag{font-size:3.5vh;margin-right:.6vh}.role{display:inline-block;margin-top:1.5vh;padding:.7vh 1.6vh;border:1px solid #fff;border-radius:999px;font-size:1.6vh;font-weight:800}.footer{text-align:center;padding:2vh 3vw 4vh;font-size:1.4vh;color:#9ca3af}.controls{position:absolute;bottom:1vh;left:1vh;opacity:.12}.controls:hover{opacity:1}.controls button{padding:.5vh}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1.5vh;width:100%}.grid .photo,.grid .placeholder{width:15vh;height:15vh;font-size:5vh}.grid .name{font-size:2vh;margin-top:.7vh}.grid .meta{font-size:1.2vh;margin-top:.4vh}</style></head><body><div class="stage"><?php if($data['test']):?><div class="test">TEST MODE</div><?php endif;?><div class="head"><div class="event"><?=e((string)$round['event_name'])?></div><div class="division"><?=e(ucwords(str_replace('_',' ',(string)$round['division'])))?> · <?=e(strtoupper((string)$round['round_type']))?></div></div><div class="screen" id="screen"></div><div class="footer">BACHATA DANCE COUNCIL · STAGE DISPLAY</div><div class="controls"><button onclick="prev()">◀</button><button onclick="toggle()" id="play">Ⅱ</button><button onclick="next()">▶</button><button onclick="grid()">Grid</button></div></div><script>const people=<?=json_encode($competitors,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;let i=0,timer=null,playing=true;const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function card(p,small=false){const image=p.photo_url?`<img class="photo" src="${esc(p.photo_url)}" onerror="this.outerHTML='<div class=placeholder>♟</div>'">`:'<div class="placeholder">♟</div>';return `<div class="person">${image}<div class="name">${esc(p.display_name)}</div><div class="meta">${p.country?esc(p.country)+' · ':''}${p.bib_number?'BIB '+esc(p.bib_number):'BIB UNASSIGNED'}</div><div class="role">${p.dance_role==='leader'?'LEADER':'FOLLOWER'}</div></div>`}function show(){document.querySelector('#screen').innerHTML=people.length?card(people[i]):'<div class="person"><div class="name">Competition lineup coming soon</div></div>'}function next(){if(people.length)i=(i+1)%people.length;show()}function prev(){if(people.length)i=(i-1+people.length)%people.length;show()}function start(){clearInterval(timer);timer=setInterval(next,6000)}function toggle(){playing=!playing;document.querySelector('#play').textContent=playing?'Ⅱ':'▶';if(playing)start();else clearInterval(timer)}function grid(){clearInterval(timer);playing=false;document.querySelector('#play').textContent='▶';document.querySelector('#screen').innerHTML='<div class="grid">'+people.slice(0,8).map(p=>card(p,true)).join('')+'</div>'}show();start();</script></body></html>